  for(let i=0;i<=7;i++){
    const y=i/7*H;
    beam(new THREE.Vector3(backX,y,-2.0),new THREE.Vector3(backX,y,2.0),0.07,M.steel,g);
  }
  beam(new THREE.Vector3(backX,1,-2.0),new THREE.Vector3(backX,H*0.55,2.0),0.05,M.steelDark,g);
  beam(new THREE.Vector3(backX,1,2.0),new THREE.Vector3(backX,H*0.55,-2.0),0.05,M.steelDark,g);
  beam(new THREE.Vector3(backX,H*0.5,-2.0),new THREE.Vector3(backX,H-1,2.0),0.05,M.steelDark,g);
  beam(new THREE.Vector3(backX,H*0.5,2.0),new THREE.Vector3(backX,H-1,-2.0),0.05,M.steelDark,g);
