  for(const z of zs) beam(new THREE.Vector3(backX,H,z),new THREE.Vector3(LIP.x-1.2,LIP.y+0.85,0),0.05,M.steelDark,g);
  // base frame + feet
  beam(new THREE.Vector3(-5,0.18,-2.3),new THREE.Vector3(backX+0.6,0.18,-2.3),0.09,M.steelDark,g);
  beam(new THREE.Vector3(-5,0.18,2.3),new THREE.Vector3(backX+0.6,0.18,2.3),0.09,M.steelDark,g);
  beam(new THREE.Vector3(backX,0,0),new THREE.Vector3(backX-6.5,0.1,-3.4),0.07,M.steelDark,g);
  beam(new THREE.Vector3(backX,0,0),new THREE.Vector3(backX-6.5,0.1,3.4),0.07,M.steelDark,g);
  // small red marker lights on tower
  for(let i=1;i<=5;i++){ const m=box(0.12,0.12,0.12,M.ledRed,backX+0.16,i*H/5.5,0); m.castShadow=false; g.add(m); }
})();
