const carGroup=new THREE.Group(); scene.add(carGroup);
function extrudeProfile(pts,width,mat,bevel=0.04){
  const sh=new THREE.Shape();
  sh.moveTo(pts[0][0],pts[0][1]);
  for(let i=1;i<pts.length;i++) sh.lineTo(pts[i][0],pts[i][1]);
  sh.closePath();
  const geo=new THREE.ExtrudeGeometry(sh,{depth:width,bevelEnabled:true,bevelThickness:bevel,bevelSize:bevel,bevelSegments:2,steps:1});
  geo.translate(0,0,-width/2);
  const m=new THREE.Mesh(geo,mat); m.castShadow=true; m.receiveShadow=true; return m;
}
