/* ---------------- reset / replay ---------------- */
const partHome={};
for(const name in parts){ const g=parts[name].group; partHome[name]={p:g.position.clone(),q:g.quaternion.clone()}; }
function readSettings(){
  const num=id=>parseFloat(document.getElementById(id).value);
  SET={ mass:clamp(num('sMass')||2000,300,6000), fanKgf:clamp(num('sFan')||0,0,12000),
        driveN:clamp((num('sDrive')||0)*1000,0,120000), thrusterN:clamp((num('sThr')||0)*1000,0,250000),
        grav:clamp(num('sGrav')||9.81,0.5,40) };
  computeInertia();
}
function resetRun(){
  readSettings();
  rng=mulberry32(1337); smokeIdx=0;
  for(const p of smokePool){ p.life=0; p.sp.visible=false; }
  clearDebris();
  // rebuild canopy glass shards case: group may have been removed from car
  for(const name in parts){
    const P=parts[name]; P.broken=false;
    const g=P.group;
    if(g.parent!==carGroup){ if(g.parent)g.parent.remove(g); carGroup.add(g); }
    g.position.copy(partHome[name].p); g.quaternion.copy(partHome[name].q); g.scale.set(1,1,1);
  }
  S.t=0; S.phase='wait'; S.phaseT=0;
  S.p.set(-11,0.97,0); S.v.set(0,0,0); S.q.identity(); S.w.set(0,0,0);
  S.throttle=0; S.fan=0; S.fanKg=0; S.grounded=true; S.airT=0; S.touched=false; S.crashed=false; S.impact=0; S.finished=false;
  for(const W of S.wheels){ W.comp=0;W.len=0.3;W.load=0;W.spin=0;W.contact=false; }
  cornerState.fill(false); wheelWasContact.fill(false);
  stallT=0; reachedSteep=false; noContactT=0; dustT=0;
  zeroThrusters();
  record.length=0; recT=0; scrubIdx=-1; liveSaved=null;
  timelineEl.max=0; timelineEl.value=0;
  document.getElementById('btnLive').disabled=true;
  setStatus('');
  accumulator=0;
}

/* ---------------- recording & scrubbing ---------------- */
const record=[]; let recT=0, scrubIdx=-1, liveSaved=null;
const REC_DT=1/30;
function snapshotPhysics(){
  return { t:S.t,phase:S.phase,phaseT:S.phaseT,
    p:S.p.clone(),v:S.v.clone(),q:S.q.clone(),w:S.w.clone(),
    throttle:S.throttle,fan:S.fan,fanKg:S.fanKg,grounded:S.grounded,airT:S.airT,
    touched:S.touched,crashed:S.crashed,impact:S.impact,
    wheels:S.wheels.map(W=>({comp:W.comp,len:W.len,load:W.load,spin:W.spin,contact:W.contact})),
    thr:NOZZLES.map(n=>n.thrust), stallT,reachedSteep,noContactT };
}
function restorePhysics(s){
  S.t=s.t;S.phase=s.phase;S.phaseT=s.phaseT;
  S.p.copy(s.p);S.v.copy(s.v);S.q.copy(s.q);S.w.copy(s.w);
  S.throttle=s.throttle;S.fan=s.fan;S.fanKg=s.fanKg;S.grounded=s.grounded;S.airT=s.airT;
  S.touched=s.touched;S.crashed=s.crashed;S.impact=s.impact;
  s.wheels.forEach((W,i)=>Object.assign(S.wheels[i],W));
  NOZZLES.forEach((n,i)=>n.thrust=s.thr[i]);
  stallT=s.stallT;reachedSteep=s.reachedSteep;noContactT=s.noContactT;
}
function recordFrame(){
  record.push({
    t:S.t, phase:S.phase,
    p:S.p.clone(), q:S.q.clone(), v:S.v.clone(),
    wl:S.wheels.map(W=>W.len), ws:S.wheels.map(W=>W.spin),
    thr:NOZZLES.map(n=>n.maxF>0?n.thrust/n.maxF:0), fan:S.fan, fanKg:S.fanKg,
    broken:Object.keys(parts).filter(n=>parts[n].broken),
    debris:debris.map(d=>({m:d.mesh,p:d.pos.clone(),q:d.quat.clone()})),
    phys:null // full physics stored sparsely on scrub demand via liveSaved
  });
  if(record.length>2400) record.shift();
  timelineEl.max=Math.max(0,record.length-1);
  if(scrubIdx<0) timelineEl.value=record.length-1;
}
function applyRecordFrame(f){
  carGroup.position.copy(f.p); carGroup.quaternion.copy(f.q);
  // show/hide parts per broken state
  for(const name in parts){
    const P=parts[name];
    const shouldShow=!f.broken.includes(name);
    if(P.group.parent===carGroup) P.group.visible=shouldShow;
  }
  debris.forEach(d=>{ /* hide all live debris while scrubbing */ d.mesh.visible=false; });
  for(const rd of f.debris){ rd.m.visible=true; rd.m.position.copy(rd.p); rd.m.quaternion.copy(rd.q); }
  NOZZLES.forEach((n,i)=>updateJetVisual(n,f.thr[i]));
  wheelGroups.forEach((wg,i)=>{
    if(wg.parent!==carGroup) return;
    wg.position.set(WHEEL_LOCAL[i].x, WHEEL_LOCAL[i].y - f.wl[i] + 0.0, WHEEL_LOCAL[i].z);
    const sp=wg.userData.spin; if(sp){ sp.tire.rotation.y=f.ws[i]; sp.disc.rotation.y=f.ws[i]; }
  });
