}

/* ---------------- visual sync ---------------- */
function updateJetVisual(n,frac){
  const on=frac>0.02;
  n.jet.visible=on; n.jetCore.visible=on;
  if(!on) return;
  const len=0.5+frac*(n.kind==='lift'?3.4:2.6);
  const wdt=0.55+frac*0.8;
  n.jet.scale.set(wdt,len,wdt);
  n.jet.material.opacity=0.10+frac*0.30;
  n.jetCore.scale.set(wdt*0.8,len*0.72,wdt*0.8);
  n.jetCore.material.opacity=0.22+frac*0.55;
}
let fanSpin=0;
function syncVisuals(dt){
  carGroup.position.copy(S.p); carGroup.quaternion.copy(S.q);
  for(const d of debris) d.mesh.visible=true;
  for(const name in parts) if(parts[name].group.parent===carGroup) parts[name].group.visible=true;
  wheelGroups.forEach((wg,i)=>{
    if(wg.parent!==carGroup) return;
    wg.position.set(WHEEL_LOCAL[i].x, WHEEL_LOCAL[i].y - S.wheels[i].len, WHEEL_LOCAL[i].z);
    const sp=wg.userData.spin;
    if(sp){ // cylinder axis is Z after rotation.x; spin around world axle = local Y of geometry holder
      sp.tire.rotation.y=S.wheels[i].spin; sp.disc.rotation.y=S.wheels[i].spin; sp.hub.rotation.y=S.wheels[i].spin;
    }
  });
  fanSpin+=S.fan*38*dt;
  for(const fm of fanMeshes){ fm.rotation.z=fanSpin; }
  let jetSum=0;
  for(const n of NOZZLES){ const fr=n.maxF>0?n.thrust/n.maxF:0; jetSum+=fr; updateJetVisual(n,fr); }
  jetLight.intensity=jetSum*260;
  if(jetSum>0.1) jetLight.position.copy(S.p);
}

/* ---------------- telemetry & status ---------------- */
const el=id=>document.getElementById(id);
const timelineEl=el('timeline');
function setStatus(s){ el('status').textContent=s; }
const PHASE_LABEL={wait:'STAGED',climb:'CLIMBING',hold:'HANGING ON FANS',release:'RELEASE',airborne:'AIRBORNE — ROLLING',hover:'HOVER — BRAKING',landed:'TOUCHDOWN',driveout:'DRIVING OUT',done:'COMPLETE',abort:'ABORT — ROLLBACK',failed:'FAILED — NO CLIMB',wreck:'CRASHED'};
function updateTelemetry(f){
  const p=f?f.p:S.p, q=f?f.q:S.q, v=f?f.v:S.v;
  _up.set(0,1,0).applyQuaternion(q); _fwd.set(1,0,0).applyQuaternion(q);
  const pitch=Math.atan2(_fwd.y,Math.hypot(_fwd.x,_fwd.z))*180/Math.PI;
  el('phase').textContent=PHASE_LABEL[f?f.phase:S.phase]||(f?f.phase:S.phase);
  el('tSpeed').textContent=v.length().toFixed(1);
  el('tPitch').textContent=pitch.toFixed(0)+'°';
  el('tHeight').textContent=Math.max(0,p.y-0.95).toFixed(1);
  el('tFan').textContent=Math.round(f?f.fanKg:S.fanKg).toLocaleString();
  const firing=NOZZLES.filter((n,i)=>((f?f.thr[i]:(n.maxF>0?n.thrust/n.maxF:0))>0.05)).map(n=>n.id);
  el('thrusters').textContent=firing.length?firing.join(' '):'—';
  const intact=Object.values(parts).filter(P=>!P.broken).length;
  el('tParts').textContent= f? (Object.keys(parts).length - f.broken.length)+'/'+Object.keys(parts).length : intact+'/'+Object.keys(parts).length;
  const tTot=record.length?record[record.length-1].t:0;
  const tCur=f?f.t:S.t;
  el('tlTime').textContent=tCur.toFixed(1)+'s / '+tTot.toFixed(1)+'s';
}
