  async function runSim(label, setupJS, seconds) {
    const out = await page.evaluate(([setupJS, seconds]) => {
      const R = window.__ramp;
      R.resetRun();
      if (setupJS) eval(setupJS);
      const DT = 1 / 240, steps = Math.floor(seconds / DT);
      const log = [];
      let maxY = 0, maxTh = 0, phasesSeen = [];
      for (let i = 0; i < steps; i++) {
        R.physStep(DT);
        const S = R.S;
        if (S.p.y > maxY) maxY = S.p.y;
        if (S.surfTh > maxTh) maxTh = S.surfTh;
        if (!phasesSeen.includes(S.phase)) phasesSeen.push(S.phase);
        if (i % 240 === 0) log.push(`t=${S.t.toFixed(1)} ph=${S.phase} p=(${S.p.x.toFixed(1)},${S.p.y.toFixed(1)},${S.p.z.toFixed(1)}) v=${S.v.length().toFixed(1)} vy=${S.v.y.toFixed(1)} s=${S.surfS.toFixed(1)} th=${(S.surfTh*180/Math.PI).toFixed(0)} fan=${S.fanKg.toFixed(0)} broke=${Object.keys(R.parts).filter(k=>R.parts[k].broken).join(',')}`);
        if (S.phase === 'done' || S.phase === 'failed') { log.push('END at t=' + S.t.toFixed(1)); break; }
        if (S.phase === 'wreck' && S.v.length() < 0.5 && S.t > 5) { log.push('WRECK settled t=' + S.t.toFixed(1)); break; }
      }
      const S = R.S;
      const up = { y: 2*(S.q.x*S.q.z + S.q.w*S.q.y) * 0 + (1 - 2*(S.q.x*S.q.x + S.q.z*S.q.z)) };
      return { log, final: { phase: S.phase, t: S.t, p: [S.p.x, S.p.y, S.p.z], v: S.v.length(), upY: up.y, maxY, maxThDeg: maxTh*180/Math.PI, phasesSeen, broken: Object.keys(R.parts).filter(k=>R.parts[k].broken), profLen: R.PROF_LEN, lip: [R.LIP.x, R.LIP.y] } };
    }, [setupJS, seconds]);
    console.log('\n=== ' + label + ' ===');
    console.log(out.log.join('\n'));
    console.log('FINAL', JSON.stringify(out.final));
    return out.final;
  }

