(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  await page.goto('file:///tmp/workspace.oOeyMl/app/index.html', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__ramp, null, { timeout: 60000 });

  async function freezeAt(tTarget, camSel, file) {
    await page.evaluate((tTarget) => {
      const R = window.__ramp;
      document.getElementById('btnPause').click(); // ensure state known below
    }, tTarget).catch(()=>{});
    // simpler: set paused via keyboard-independent route
    await page.evaluate((tTarget) => {
      const R = window.__ramp;
      R.resetRun();
      const DT = 1/240;
      while (R.S.t < tTarget) R.physStep(DT);
      R.syncVisuals(0.016);
      window.__frozen = true;
    }, tTarget);
    if (camSel) await page.click(camSel);
    await page.waitForTimeout(350);
    // re-sync after any rAF stepping that may have occurred while unpaused
    await page.screenshot({ path: file });
    const st = await page.evaluate(() => { const S = window.__ramp.S; return `t=${S.t.toFixed(1)} ph=${S.phase} p=${S.p.x.toFixed(1)},${S.p.y.toFixed(1)}`; });
    console.log(file, st);
  }

  // Pause the run first so manual stepping isn't fighting rAF too much (tolerable drift)
  await freezeAt(0.4, '[data-cam="foot"]', '/tmp/shot_foot.png');
  await freezeAt(3.0, '[data-cam="wide"]', '/tmp/shot_climb.png');
  await freezeAt(6.0, '[data-cam="lip"]', '/tmp/shot_hold.png');
  await freezeAt(9.2, '[data-cam="wide"]', '/tmp/shot_air.png');
  await freezeAt(11.6, '[data-cam="wide"]', '/tmp/shot_hover.png');
  await freezeAt(6.0, '[data-cam="aerial"]', '/tmp/shot_aerial.png');
  await freezeAt(9.0, '[data-cam="drone"]', '/tmp/shot_drone.png');

  // UI interactions
  await page.click('#btnReplay');
  await page.waitForTimeout(400);
  await page.keyboard.press('Space'); // pause
  await page.waitForTimeout(150);
  const pausedLabel = await page.textContent('#btnPause');
  await page.keyboard.press('Space'); // play
  await page.click('[data-speed="0.25"]');
  await page.click('[data-speed="1"]');
  await page.click('[data-cam="chase"]');
  await page.waitForTimeout(300);
  await page.click('[data-cam="orbit"]');
  await page.mouse.move(640, 360); await page.mouse.down(); await page.mouse.move(760, 300); await page.mouse.up();
  await page.waitForTimeout(200);
  // timeline scrub
  const tlMax = await page.evaluate(() => document.getElementById('timeline').max);
  await page.evaluate(() => { const t = document.getElementById('timeline'); t.value = Math.floor(t.max/2); t.dispatchEvent(new Event('input')); });
  await page.waitForTimeout(200);
  const liveDisabled = await page.evaluate(() => document.getElementById('btnLive').disabled);
  await page.click('#btnLive');
  await page.waitForTimeout(200);
  // settings + failure button
  await page.click('#btnFailThr');
  await page.waitForTimeout(300);
  const thrVal = await page.evaluate(() => document.getElementById('sThr').value);
  await page.click('#btnDefaults');
  await page.waitForTimeout(300);
  const tel = await page.evaluate(() => document.getElementById('telemetry').innerText.replace(/\n/g,' | '));
  console.log('UI: pausedLabel=', pausedLabel, 'tlMax=', tlMax, 'liveEnabledDuringScrub=', !liveDisabled, 'thrAfterFail=', thrVal);
  console.log('TELEMETRY:', tel);
  console.log('ERRORS:', JSON.stringify(errors.slice(0,10)));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
"}

