  await page.waitForFunction(() => window.__ramp, null, { timeout: 60000 });

  async function ensurePaused() {
    const label = await page.textContent('#btnPause');
    if (!label.includes('Play')) await page.click('#btnPause');
  }
  async function ensurePlaying() {
    const label = await page.textContent('#btnPause');
    if (label.includes('Play')) await page.click('#btnPause');
  }
  async function freezeAt(t, cam, file) {
    await ensurePaused();
    await page.evaluate((t) => {
      const R = window.__ramp; R.resetRun();
      const DT = 1/240;
      while (R.S.t < t) R.physStep(DT);
      R.syncVisuals(0.016);
    }, t);
    if (cam) await page.click(cam);
    await page.waitForTimeout(450);
    await page.evaluate(() => window.__ramp.syncVisuals(0.016));
    await page.waitForTimeout(80);
    await page.screenshot({ path: file });
    console.log(file, await page.evaluate(() => { const S = window.__ramp.S; return `t=${S.t.toFixed(1)} ph=${S.phase} p=${S.p.x.toFixed(1)},${S.p.y.toFixed(1)}`; }));
  }

  await freezeAt(0.5, '[data-cam="foot"]', '/tmp/v2_foot.png');
  await freezeAt(3.2, '[data-cam="wide"]', '/tmp/v2_climb.png');
  await freezeAt(6.0, '[data-cam="lip"]', '/tmp/v2_hold.png');
  await freezeAt(9.0, '[data-cam="wide"]', '/tmp/v2_air.png');
  await freezeAt(11.3, '[data-cam="wide"]', '/tmp/v2_hover.png');
  await freezeAt(9.2, '[data-cam="drone"]', '/tmp/v2_drone.png');
  await freezeAt(6.0, '[data-cam="aerial"]', '/tmp/v2_aerial.png');
  // touchdown smoke: step near, then play briefly
  await freezeAt(12.7, '[data-cam="wide"]', '/tmp/v2_pretd.png');
  await ensurePlaying();
  await page.waitForTimeout(650);
  await page.screenshot({ path: '/tmp/v2_touchdown.png' });
  console.log('touchdown', await page.evaluate(() => { const S = window.__ramp.S; return `t=${S.t.toFixed(1)} ph=${S.phase}`; }));
  await ensurePaused();

  // sensitivity sweep (physics only)
  const sens = await page.evaluate(() => {
    const R = window.__ramp;
    const runs = [
      ['mass2600', { sMass: 2600 }], ['mass1500', { sMass: 1500 }],
      ['grav12', { sGrav: 12 }], ['grav3.7', { sGrav: 3.7 }],
      ['thr40', { sThr: 40 }], ['fan3000', { sFan: 3000 }],
      ['fan2000', { sFan: 2000 }], ['drive30', { sDrive: 30 }], ['drive20', { sDrive: 20 }],
    ];
    const out = [];
    for (const [name, kv] of runs) {
      document.getElementById('sMass').value=2000; document.getElementById('sFan').value=4700;
      document.getElementById('sDrive').value=45; document.getElementById('sThr').value=75; document.getElementById('sGrav').value=9.81;
      for (const k in kv) document.getElementById(k).value = kv[k];
      R.resetRun();
      const DT = 1/240;
      for (let i = 0; i < 240*30; i++) { R.physStep(DT); if (['done','failed'].includes(R.S.phase)) break; if (R.S.phase==='wreck' && R.S.v.length()<0.5 && R.S.t>4) break; }
      out.push(name + ': ' + R.S.phase + ' broken=[' + Object.keys(R.parts).filter(k=>R.parts[k].broken).join(',') + ']');
    }
    return out;
  });
  console.log(sens.join('\n'));
  console.log('ERRORS:', JSON.stringify(errors.slice(0,10)));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
"}

