{"path":"/tmp/final_check.cjs","content":"const { chromium } = require('/root/.dev-browser/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  await page.goto('file:///tmp/workspace.oOeyMl/app/index.html', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__ramp, null, { timeout: 60000 });
  console.log('title:', await page.title());
  // REAL-TIME autostart: do not touch anything; sample phase over time at 2x to save wall time
  await page.click('[data-speed="2"]');
  const seen = [];
  for (let i = 0; i < 26; i++) {
    await page.waitForTimeout(400);
    const ph = await page.evaluate(() => document.getElementById('phase').textContent + '@' + window.__ramp.S.t.toFixed(1));
    if (!seen.includes(ph.split('@')[0])) seen.push(ph.split('@')[0]);
    if (ph.startsWith('COMPLETE')) { console.log('realtime reached COMPLETE, sim t=', ph.split('@')[1]); break; }
    if (i === 25) console.log('realtime last:', ph);
  }
  console.log('realtime phases:', seen.join(' -> '));
  const fin = await page.evaluate(() => { const R = window.__ramp; return { phase: R.S.phase, broken: Object.keys(R.parts).filter(k=>R.parts[k].broken), parts: document.getElementById('tParts').textContent, status: document.getElementById('status').textContent }; });
  console.log('realtime final:', JSON.stringify(fin));
  // frozen beauty shots with new lighting
  async function ensurePaused(){ const l = await page.textContent('#btnPause'); if (!l.includes('Play')) await page.click('#btnPause'); }
  async function freezeAt(t, cam, file){
    await ensurePaused();
    await page.evaluate((t) => { const R = window.__ramp; R.resetRun(); const DT=1/240; while (R.S.t < t) R.physStep(DT); R.syncVisuals(0.016); }, t);
    if (cam) await page.click(cam);
    await page.waitForTimeout(450);
    await page.evaluate(() => window.__ramp.syncVisuals(0.016));
    await page.waitForTimeout(80);
    await page.screenshot({ path: file });
    console.log(file, 'done');
  }
  await page.click('[data-speed="1"]');
  await freezeAt(0.5, '[data-cam="foot"]', '/tmp/v5_foot.png');
  await freezeAt(6.0, '[data-cam="lip"]', '/tmp/v5_hold.png');
  await freezeAt(9.0, '[data-cam="wide"]', '/tmp/v5_air.png');
  await freezeAt(11.3, '[data-cam="wide"]', '/tmp/v5_hover.png');
  console.log('ERRORS:', JSON.stringify(errors.slice(0,10)));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
"}
